  backup_confirm_overwrite:{ ko:'슬롯 {n}의 기존 기록이 삭제되고 현재 목록으로 교체됩니다. 계속할까요?', en:"Slot {n}'s existing data will be deleted and replaced with the current list. Continue?", id:'Data yang ada di Slot {n} akan dihapus dan diganti dengan daftar saat ini. Lanjutkan?', zh:'插槽 {n} 的现有记录将被删除并替换为当前列表。是否继续？', ja:'スロット{n}の既存データが削除され、現在のリストに置き換わります。続けますか？', es:'Los datos existentes en la Ranura {n} se eliminarán y se reemplazarán con la lista actual. ¿Continuar?', vi:'Dữ liệu hiện có trong Khe {n} sẽ bị xóa và thay bằng danh sách hiện tại. Tiếp tục?', hi:'स्लॉट {n} का मौजूदा डेटा हटा दिया जाएगा और वर्तमान सूची से बदल दिया जाएगा। जारी रखें?', pt:'Os dados existentes no Slot {n} serão excluídos e substituídos pela lista atual. Continuar?', tl:'Ang datos sa Slot {n} ay tatanggalin at papalitan ng kasalukuyang listahan. Magpatuloy?', fr:"Les données existantes de l'emplacement {n} seront supprimées et remplacées par la liste actuelle. Continuer ?" },
  backup_confirm_save:     { ko:'슬롯 {n}에 현재 목록을 백업합니다.', en:'Back up the current list to Slot {n}.', id:'Backup daftar saat ini ke Slot {n}.', zh:'将当前列表备份到插槽 {n}。', ja:'現在のリストをスロット{n}にバックアップします。', es:'Respaldar la lista actual en la Ranura {n}.', vi:'Sao lưu danh sách hiện tại vào Khe {n}.', hi:'वर्तमान सूची को स्लॉट {n} में बैकअप करें।', pt:'Fazer backup da lista atual no Slot {n}.', tl:'I-backup ang kasalukuyang listahan sa Slot {n}.', fr:"Sauvegarder la liste actuelle dans l'emplacement {n}." },
  backup_confirm_truncate: { ko:'최대 {n}개까지만 저장되고 {dropped}개는 제외됩니다. 계속할까요?', en:'Only up to {n} will be saved and {dropped} will be dropped. Continue?', id:'Hanya {n} yang akan disimpan dan {dropped} akan dibuang. Lanjutkan?', zh:'最多只能保存 {n} 个，{dropped} 个将被排除。是否继续？', ja:'最大{n}個のみ保存され、{dropped}個は除外されます。続けますか？', es:'Solo se guardarán hasta {n} y se descartarán {dropped}. ¿Continuar?', vi:'Chỉ {n} mục sẽ được lưu và {dropped} mục sẽ bị loại bỏ. Tiếp tục?', hi:'केवल {n} तक सहेजे जाएंगे और {dropped} हटा दिए जाएंगे। जारी रखें?', pt:'Apenas {n} serão salvos e {dropped} serão descartados. Continuar?', tl:'{n} lang ang mase-save at {dropped} ang aalisin. Magpatuloy?', fr:'Seuls {n} seront enregistrés et {dropped} seront exclus. Continuer ?' },
  backup_confirm_restore_full:{ ko:'현재 목록이 모두 지워지고 슬롯 {n}의 내용으로 교체됩니다. 계속할까요?', en:'The current list will be cleared and replaced with Slot {n}. Continue?', id:'Daftar saat ini akan dihapus dan diganti dengan isi Slot {n}. Lanjutkan?', zh:'当前列表将被清空并替换为插槽 {n} 的内容。是否继续？', ja:'現在のリストがすべて削除され、スロット{n}の内容に置き換わります。続けますか？', es:'La lista actual se borrará y se reemplazará con el contenido de la Ranura {n}. ¿Continuar?', vi:'Danh sách hiện tại sẽ bị xóa và thay bằng nội dung của Khe {n}. Tiếp tục?', hi:'वर्तमान सूची पूरी तरह हटा दी जाएगी और स्लॉट {n} की सामग्री से बदल दी जाएगी। जारी रखें?', pt:'A lista atual será apagada e substituída pelo conteúdo do Slot {n}. Continuar?', tl:'Ang kasalukuyang listahan ay tatanggalin at papalitan ng laman ng Slot {n}. Magpatuloy?', fr:"La liste actuelle sera effacée et remplacée par le contenu de l'emplacement {n}. Continuer ?" },
