  info_about:       { ko:'앱 소개',    en:'About',                 id:'Tentang Aplikasi',   zh:'应用介绍',      ja:'アプリ紹介',           es:'Acerca de',              vi:'Giới thiệu ứng dụng',  hi:'ऐप के बारे में',  pt:'Sobre o App',            tl:'Tungkol sa App',          fr:'À propos' },
  info_notice:      { ko:'시뮬레이션 전용', en:'Simulation Only',  id:'Hanya Simulasi',     zh:'仅供模拟',      ja:'シミュレーション専用', es:'Solo Simulación',        vi:'Chỉ để mô phỏng',      hi:'केवल सिमुलेशन',   pt:'Somente Simulação',      tl:'Para sa Simulation Lamang', fr:'Simulation Uniquement' },
  info_notice_desc: { ko:'이 앱은 분석·시뮬레이션 도구입니다. 실제 거래는 Pi Browser의 PiDEX에서 직접 진행해주세요.', en:'This app is for analysis only. Execute trades on PiDEX in Pi Browser.', id:'Aplikasi ini hanya untuk analisis. Lakukan perdagangan nyata di PiDEX pada Pi Browser.', zh:'本应用仅为分析/模拟工具，请在Pi Browser的PiDEX中直接进行实际交易。', ja:'このアプリは分析・シミュレーションツールです。実際の取引はPi BrowserのPiDEXで行ってください。', es:'Esta app es solo para análisis. Ejecute las operaciones reales en PiDEX en Pi Browser.', vi:'Ứng dụng này chỉ để phân tích. Hãy thực hiện giao dịch thực tế trên PiDEX trong Pi Browser.', hi:'यह ऐप केवल विश्लेषण के लिए है। वास्तविक लेनदेन Pi Browser के PiDEX पर करें।', pt:'Este app é apenas para análise. Execute as negociações reais no PiDEX no Pi Browser.', tl:'Ang app na ito ay para sa pagsusuri lamang. Isagawa ang mga aktwal na trade sa PiDEX sa Pi Browser.', fr:"Cette application est réservée à l'analyse. Effectuez les transactions réelles sur PiDEX dans Pi Browser." },
  info_pubkey:      { ko:'지갑 공개주소 등록', en:'Register Wallet Address', id:'Daftarkan Alamat Dompet', zh:'注册钱包公开地址', ja:'ウォレット公開アドレス登録', es:'Registrar dirección de cartera', vi:'Đăng ký địa chỉ ví công khai', hi:'वॉलेट सार्वजनिक पता रजिस्टर करें', pt:'Registrar endereço público da carteira', tl:'I-register ang Wallet Address', fr:"Enregistrer l'adresse publique" },
  info_pubkey_desc: { ko:'Pi 지갑의 공개주소(G로 시작, 56자리)를 등록하면 지갑 탭이 활성화됩니다.\n총 보유 Pi, 토큰 잔액, LP 예치 현황 등을 확인할 수 있습니다. 공개주소는 읽기 전용으로 안전합니다.', en:'Register your public key (G..., 56 chars) to activate the Wallet tab and view Pi balance, tokens, and LP positions. Public key is read-only and safe.', id:'Daftarkan kunci publik Pi Anda (G..., 56 karakter) untuk mengaktifkan tab Dompet dan melihat saldo Pi, token, dan posisi LP. Kunci publik hanya untuk baca dan aman.', zh:'注册Pi钱包公开地址（以G开头，56位）可激活钱包选项卡，查看Pi余额、代币余额和LP质押状况。公开地址仅读取，安全可靠。', ja:'Pi ウォレットの公開アドレス（G始まり、56文字）を登録するとウォレットタブが有効になります。総保有Pi・トークン残高・LP預入状況等を確認できます。公開アドレスは読み取り専用で安全です。', es:'Registre su clave pública (G..., 56 chars) para activar la pestaña Cartera y ver saldo Pi, tokens y posiciones LP. La clave pública es de solo lectura y segura.', vi:'Đăng ký khóa công khai Pi (G..., 56 ký tự) để kích hoạt tab Ví và xem số dư Pi, token và vị thế LP. Khóa công khai chỉ đọc và an toàn.', hi:'Pi वॉलेट का सार्वजनिक पता (G..., 56 अक्षर) रजिस्टर करें। वॉलेट टैब सक्रिय होगा। Pi बैलेंस, टोकन और LP पोजीशन देखें। सुरक्षित।', pt:'Registre sua chave pública Pi (G..., 56 chars) para ativar a aba Carteira e ver saldo Pi, tokens e posições LP. Chave pública é somente leitura e segura.', tl:'I-register ang inyong public key ng Pi (G..., 56 character) para ma-activate ang Wallet tab at makita ang Pi balance, tokens at LP positions. Ligtas ang public key.', fr:"Enregistrez votre clé publique Pi (G..., 56 chars) pour activer l'onglet Portefeuille et voir votre solde Pi, tokens et positions LP. La clé publique est en lecture seule et sécurisée." },
  info_registered:  { ko:'등록됨', en:'Active', id:'Terdaftar', zh:'已注册', ja:'登録済み', es:'Activo', vi:'Đã đăng ký', hi:'पंजीकृत', pt:'Ativo', tl:'Nairehistro', fr:'Enregistré' },
