function _detectLang() {
  const supported = ['ko','en','id','zh','ja','es','vi','hi','pt','tl','fr'];
  const nav = (navigator.languages?.[0] || navigator.language || 'en').toLowerCase();
  const primary = nav.split('-')[0];
  if (primary === 'fil') return 'tl';
  return supported.includes(primary) ? primary : 'en';
}
let _lang = localStorage.getItem('pidex_lang') || _detectLang();

export function getLang() { return _lang; }

export function setLang(lang) {
  _lang = lang;
  localStorage.setItem('pidex_lang', lang);
}

export function t(key) {
  const s = STRINGS[key];
  if (!s) return key;
  return s[_lang] ?? s.ko;
}
